#!/usr/bin/env python3
"""Render THIRD-PARTY-NOTICES.md from cargo-about and pnpm licence data.

Called by scripts/licenses/generate-notices.sh; see that script and the
"How this file is made" section of the output for what goes in. The output
is deterministic for a given set of inputs: entries are sorted, machine paths
never appear, and every licence text goes in a fenced block so Markdown
formatting cannot rewrite it.
"""

from __future__ import annotations

import argparse
import json
import os
import re
import sys

GENERATED_MARK = (
    "<!-- Everything below is generated by scripts/licenses/generate-notices.sh "
    "from Cargo.lock and pnpm-lock.yaml. Do not edit it by hand. -->"
)

LICENSE_FILE = re.compile(r"^(licen[cs]e|copying)([-._].*)?$", re.IGNORECASE)


def fence(text: str) -> str:
    """`text` in a fence longer than any backtick run inside it."""
    longest = max((len(m) for m in re.findall(r"`+", text)), default=0)
    ticks = "`" * max(4, longest + 1)
    return f"{ticks}text\n{text}\n{ticks}"


def clean(text: str) -> str:
    """Strip trailing spaces and surrounding blank lines; keep the words."""
    lines = [line.rstrip() for line in text.replace("\r\n", "\n").replace("\r", "\n").split("\n")]
    while lines and not lines[0]:
        lines.pop(0)
    while lines and not lines[-1]:
        lines.pop()
    # Dedent a text that is uniformly indented (some crates indent the whole
    # licence), so the block reads like the original file.
    indents = [len(l) - len(l.lstrip(" ")) for l in lines if l.strip()]
    cut = min(indents) if indents else 0
    return "\n".join(l[cut:] for l in lines)


def anchor(text: str) -> str:
    return re.sub(r"[^a-z0-9-]", "", text.lower().replace(" ", "-"))


def rust_sections(sources: list[tuple[str, dict]]):
    """Group every licence text across the given cargo-about outputs.

    Crates with no registry source are this repository's own (the app and
    the Explorer extension): LICENSE is their notice, so they are left out.
    """
    groups: dict[tuple[str, str], dict] = {}
    crates: dict[tuple[str, str], dict] = {}
    for component, data in sources:
        for lic in data["licenses"]:
            text = clean(lic["text"])
            key = (lic["id"], text)
            group = groups.setdefault(
                key, {"id": lic["id"], "name": lic["name"], "text": text, "used_by": {}}
            )
            for used in lic["used_by"]:
                c = used["crate"]
                if not c.get("source"):
                    continue
                ck = (c["name"], c["version"])
                group["used_by"][ck] = c
                entry = crates.setdefault(
                    ck,
                    {
                        "name": c["name"],
                        "version": c["version"],
                        "declared": c.get("license") or "",
                        "used": set(),
                        "components": set(),
                    },
                )
                entry["used"].add(lic["id"])
                entry["components"].add(component)
    groups = {k: g for k, g in groups.items() if g["used_by"]}
    return groups, crates


def crate_link(c: dict) -> str:
    return c.get("repository") or f"https://crates.io/crates/{c['name']}"


def render_rust(groups, crates) -> list[str]:
    out = ["## Rust crates", ""]
    out.append(
        f"{len(crates)} crates are compiled into the shipped binaries. The table "
        "names each one, the licence it is offered under, the licence Pluryprint "
        "uses it under, and where it ships; the licence texts follow, each with "
        "the crates that ship it."
    )
    out.append("")
    out.append("| Crate | Version | Offered under | Used under | Ships in |")
    out.append("| --- | --- | --- | --- | --- |")
    for (name, version), c in sorted(crates.items()):
        used = ", ".join(sorted(c["used"]))
        where = ", ".join(sorted(c["components"]))
        declared = c["declared"].replace("|", "\\|") or "see licence file"
        out.append(f"| `{name}` | {version} | {declared} | {used} | {where} |")
    out.append("")
    out.append("### Licence texts of the Rust crates")
    out.append("")
    ordered = sorted(
        groups.values(),
        key=lambda g: (g["id"], sorted(g["used_by"])[0]),
    )
    for i, g in enumerate(ordered, 1):
        users = sorted(g["used_by"].values(), key=lambda c: (c["name"], c["version"]))
        out.append(f"#### {i}. {g['name']} ({g['id']})")
        out.append("")
        out.append("Used by:")
        out.append("")
        for c in users:
            authors = ", ".join(a.split(" <")[0] for a in (c.get("authors") or []))
            line = f"- `{c['name']}` {c['version']} ({crate_link(c)})"
            if authors:
                line += f", by {authors}"
            out.append(line)
        out.append("")
        out.append(fence(g["text"]))
        out.append("")
    return out


def package_licence_text(path: str) -> tuple[str, str] | None:
    try:
        names = sorted(os.listdir(path))
    except OSError:
        return None
    for n in names:
        if LICENSE_FILE.match(n) and os.path.isfile(os.path.join(path, n)):
            with open(os.path.join(path, n), encoding="utf-8", errors="replace") as f:
                return n, clean(f.read())
    return None


def frontend_packages(pnpm: dict, node_modules: str, extra: list[str]) -> list[dict]:
    pkgs = {}
    for licence, entries in pnpm.items():
        for e in entries:
            if e["name"].startswith("@types/"):
                continue
            for version, path in zip(e["versions"], e["paths"]):
                pkgs[(e["name"], version)] = {
                    "name": e["name"],
                    "version": version,
                    "license": e.get("license") or licence,
                    "homepage": e.get("homepage") or "",
                    "path": path,
                }
    for name in extra:
        path = os.path.realpath(os.path.join(node_modules, name))
        with open(os.path.join(path, "package.json"), encoding="utf-8") as f:
            meta = json.load(f)
        pkgs[(name, meta["version"])] = {
            "name": name,
            "version": meta["version"],
            "license": meta.get("license", ""),
            "homepage": meta.get("homepage", ""),
            "path": path,
        }
    return [pkgs[k] for k in sorted(pkgs)]


def render_frontend(pkgs: list[dict]) -> list[str]:
    out = ["## Frontend packages", ""]
    out.append(
        f"{len(pkgs)} packages have code in the bundled JavaScript and CSS. "
        "Each one's own licence file follows."
    )
    out.append("")
    out.append("| Package | Version | Licence |")
    out.append("| --- | --- | --- |")
    for p in pkgs:
        out.append(f"| `{p['name']}` | {p['version']} | {p['license']} |")
    out.append("")
    for p in pkgs:
        out.append(f"### `{p['name']}` {p['version']}")
        out.append("")
        if p["homepage"]:
            out.append(f"{p['license']}. {p['homepage']}")
        else:
            out.append(f"{p['license']}.")
        out.append("")
        found = package_licence_text(p["path"])
        if found is None:
            raise SystemExit(
                f"{p['name']} {p['version']} ships no licence file in {p['path']}; "
                "add its notice to scripts/licenses/notices-header.md by hand"
            )
        out.append(fence(found[1]))
        out.append("")
    return out


def main(argv: list[str]) -> int:
    ap = argparse.ArgumentParser()
    ap.add_argument("--header", required=True)
    ap.add_argument("--nsis", required=True)
    ap.add_argument("--app", required=True, help="cargo-about JSON for src-tauri")
    ap.add_argument("--shellext", required=True, help="cargo-about JSON for shell-ext-win")
    ap.add_argument("--pnpm", required=True, help="pnpm licenses list --prod --json")
    ap.add_argument("--node-modules", required=True)
    ap.add_argument("--extra-package", action="append", default=[])
    ap.add_argument("--out", required=True)
    args = ap.parse_args(argv)

    with open(args.header, encoding="utf-8") as f:
        header = f.read()
    with open(args.nsis, encoding="utf-8") as f:
        nsis = clean(f.read())
    header = header.replace("{{NSIS_COPYING}}", nsis)

    sources = []
    for component, path in (("app", args.app), ("Explorer extension (Windows)", args.shellext)):
        with open(path, encoding="utf-8") as f:
            sources.append((component, json.load(f)))
    groups, crates = rust_sections(sources)

    with open(args.pnpm, encoding="utf-8") as f:
        pnpm = json.load(f)
    pkgs = frontend_packages(pnpm, args.node_modules, args.extra_package)

    lines = [header.rstrip("\n"), "", GENERATED_MARK, ""]
    lines += render_rust(groups, crates)
    lines += render_frontend(pkgs)
    text = "\n".join(lines).rstrip("\n") + "\n"
    with open(args.out, "w", encoding="utf-8") as f:
        f.write(text)
    print(f"{len(crates)} crates, {len(groups)} licence texts, {len(pkgs)} frontend packages")
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv[1:]))
